window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a139cad1dc846eff"]={"versions": [{"id": "FIG-a139cad1dc846eff", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Metamodell- bzw. Strukturdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology (<code>AUTOSAR_TR_AdaptiveMethodology</code>). Es veranschaulicht die Zerlegung und Zusammensetzung eines Manifest-Artefakts (<code>Service Instance Manifest</code>) in modellhafte Definitionsbestandteile auf Konzept-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\"><li>Übergeordnete Manifest-Entität: <code>Service Instance Manifest</code> (symbolisiert durch ein Briefumschlags-Icon).\n</li><li>Untergeordnete Bestandteile / Dokumentmodelle: <code>Service Interface</code> (Schnittstellenbeschreibung) und <code>Service Instance</code> (Instanzbeschreibung), dargestellt als Dokument-Piktogramme.\n</li><li>Beziehungen: Zwei gerichtete Aggregations- bzw. Kompositionsbeziehungen vom <code>Service Instance Manifest</code> zu den jeweiligen Elementen, annotiert mit dem Stereotyp <code>«nesting»</code> und einer offenen Raute an der Container-Seite.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm ist rein statisch-struktureller Natur. Es beschreibt keine dynamischen Abläufe, Kontrollflüsse oder zeitlichen Sequenzen, sondern definiert die hierarchische Bündelung («nesting») von Spezifikationsdokumenten innerhalb eines Service Instance Manifests.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsvorgabe für Entwickler und AUTOSAR-Authoring-Tools zur Strukturierung von Manifest-Dateien: Ein <code>Service Instance Manifest</code> kapselt die Konfigurationen von <code>Service Interface</code> und <code>Service Instance</code>. Integratoren müssen sicherstellen, dass die Schnittstellendefinitionen und deren Instanziierungen in den entsprechenden Manifest-Strukturen konform gebündelt vorliegen.</p>"}, {"id": "FIG-ed518d281e646b45", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Metamodell- bzw. Strukturdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology (<code>AUTOSAR_TR_AdaptiveMethodology</code>). Es veranschaulicht die Zerlegung und Zusammensetzung eines Manifest-Artefakts (<code>Service Instance Manifest</code>) in vier geschachtelte Modell- und Mapping-Bestandteile auf Konzept-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Relationen:</p>\n<ul class=\"fig-list\"><li>Übergeordnete Manifest-Entität: <code>Service Instance Manifest</code> (symbolisiert als Briefumschlags-Icon).\n</li><li>Untergeordnete Modellelemente (Dokument-Icons):\n<ul class=\"fig-list\"><li><code>Service Interface</code>\n</li><li><code>Service Instance</code>\n</li><li><code>Service Instance To...</code> (Service Instance Mapping)\n</li><li><code>Service Instance...</code> (weitere Service-Instanz-Spezifikation bzw. Deployment-Konfiguration)\n</li></ul>\n</li><li>Beziehungen: Vier parallele Kompositionsrelationen vom <code>Service Instance Manifest</code> zu den jeweiligen Teilelementen, jeweils gekennzeichnet durch eine offene Raute am Container und die Stereotyp-Beschriftung <code>«nesting»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm ist rein statisch-struktureller Natur. Es beschreibt keine dynamischen Abläufe, Kontrollflüsse oder zeitlichen Sequenzen, sondern definiert die hierarchische Bündelung («nesting») von Spezifikationsdokumenten innerhalb eines Service Instance Manifests.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Strukturvorgabe für Adaptive AUTOSAR Manifest-Modelle: Ein vollständiges <code>Service Instance Manifest</code> fasst neben der Servicedefinition (<code>Service Interface</code>) und Serviceinstanziierung (<code>Service Instance</code>) auch die entsprechenden Mappings (<code>Service Instance To...</code>) sowie weitere instanzspezifische Konfigurationen zusammen. Authoring- und Generierungswerkzeuge müssen alle vier geschachtelten Artefaktanteile konsistent zusammenführen.</p>"}, {"id": "FIG-045e3450f5b194a1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Metamodell- bzw. Strukturdiagramm im Kontext der AUTOSAR Adaptive Platform Methodology (<code>AUTOSAR_TR_AdaptiveMethodology</code>). Es veranschaulicht die Zerlegung und Zusammensetzung eines Manifest-Artefakts (<code>Service Instance Manifest</code>) in vier geschachtelte Modell- und Mapping-Bestandteile auf Konzept-Ebene.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Komponenten und Relationen:</p>\n<ul class=\"fig-list\"><li>Übergeordnete Manifest-Entität: <code>Service Instance Manifest</code> (symbolisiert als Briefumschlags-Icon).\n</li><li>Untergeordnete Modellelemente (Dokument-Icons):\n<ul class=\"fig-list\"><li><code>Service Interface</code>\n</li><li><code>Service Instance</code>\n</li><li><code>Service Instance To...</code> (Service Instance Mapping)\n</li><li><code>Service Instance...</code> (weitere Service-Instanz-Spezifikation bzw. Deployment-Konfiguration)\n</li></ul>\n</li><li>Beziehungen: Vier parallele Kompositionsrelationen vom <code>Service Instance Manifest</code> zu den jeweiligen Teilelementen, jeweils gekennzeichnet durch eine offene Raute am Container und die Stereotyp-Beschriftung <code>«nesting»</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm ist rein statisch-struktureller Natur. Es beschreibt keine dynamischen Abläufe, Kontrollflüsse oder zeitlichen Sequenzen, sondern definiert die hierarchische Bündelung («nesting») von Spezifikationsdokumenten innerhalb eines Service Instance Manifests.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliche Strukturvorgabe für Adaptive AUTOSAR Manifest-Modelle: Ein vollständiges <code>Service Instance Manifest</code> fasst neben der Servicedefinition (<code>Service Interface</code>) und Serviceinstanziierung (<code>Service Instance</code>) auch die entsprechenden Mappings (<code>Service Instance To...</code>) sowie weitere instanzspezifische Konfigurationen zusammen. Authoring- und Generierungswerkzeuge müssen alle vier geschachtelten Artefaktanteile konsistent zusammenführen.</p>"}], "trans": [{"from": "FIG-a139cad1dc846eff", "to": "FIG-ed518d281e646b45", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die Kompositionsstruktur des Service Instance Manifests wurde von zwei auf vier geschachtelte Modellelemente («nesting») erweitert: Ergänzung von „Service Instance To...“ (Service Instance To Port Prototype Mapping / Service Instance To Machine Mapping) und einer weiteren „Service Instance...“-Spezifikation neben „Service Interface“ und „Service Instance“.\n</li></ul>"}, {"from": "FIG-ed518d281e646b45", "to": "FIG-045e3450f5b194a1", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
